<span class="line"><span style="color:#61AFEF;">k8s-master</span><span style="color:#98C379;">   Ready</span><span style="color:#ABB2BF;">      &lt;</span><span style="color:#98C379;">non</span><span style="color:#ABB2BF;">e&gt;   </span><span style="color:#98C379;">44h</span><span style="color:#98C379;">     v1.20.10</span></span>
